TAGOBJ=6be384d848f6cade3cd74a7ef430b8c82a495422; COMMIT=f3c4ea5d9d4f6ef27670851e4c94958cce98a5a6; PROTO=fccacf04f
exec > $L 2>&1
fin() { echo "RELBUILD_BPP_DONE $1 $(date -u +%FT%TZ)"; exit 0; }
echo "start $(date -u +%FT%TZ)"
pgrep -u $USER -x monerod > /dev/null && { echo "a monerod runs"; fin FAIL; }
[ "$(df --output=avail -BG / | tail -1 | tr -dc 0-9)" -ge 30 ] || { echo "under 30 GB free"; fin FAIL; }
