  mkdir -p build/release
  (cd build/release && cmake -G Ninja -DCMAKE_TOOLCHAIN_FILE=$TC -DCMAKE_BUILD_TYPE=Release -DARCH=default -DSTATIC=ON -DBUILD_TESTS=OFF ../.. > $W/relbuild_bpp_configure_$2.log 2>&1) || return 1
